def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    kid_patches = image_patch.find("kid")
    if not kid_patches: 
        return image_patch
    kid_patch = kid_patches[0]
    down_distance = float('inf')
    down_patch = None
    for obj_name in ["ground", "floor"]:
        obj_patches = image_patch.find(obj_name)
        for obj_patch in obj_patches:
            if kid_patch.overlaps_with(*obj_patch.bbox()):
                continue
            dist = abs(kid_patch.vertical_center - obj_patch.vertical_center)
            if dist < down_distance:
                down_distance = dist
                down_patch = obj_patch
    if down_patch:
        kid_patch = kid_patch.crop(max(0, int(down_patch.left)), max(0, int(down_patch.lower)), min(int(down_patch.right), kid_patch.width), min(int(down_patch.upper), kid_patch.height))
    return kid_patch

