    vehicles_patches = image_patch.find("vehicle")

    if not people_patches or not vehicles_patches:
        return image_patch

    person_centers = [(p.horizontal_center, p.vertical_center) for p in people_patches]
    vehicle_centers = [(v.horizontal_center, v.vertical_center) for v in vehicles_patches]

    min_distance = float('inf')
    closest_person = None
    closest_vehicle = None

    for person_center in person_centers:
        for vehicle_center in vehicle_centers:
            distance = math.sqrt((person_center[0] - vehicle_center[0]) ** 2 + (person_center[1] - vehicle_center[1]) ** 2)
            if distance < min_distance:
                min_distance = distance
                closest_person = next(p for p in people_patches if (p.horizontal_center, p.vertical_center) == person_center)
                closest_vehicle = next(v for v in vehicles_patches if (v.horizontal_center, v.vertical_center) == vehicle_center)

    if closest_person.overlaps_with(closest_vehicle.left, closest_vehicle.lower, closest_vehicle.right, closest_vehicle.upper):
        return closest_person
    else:
        return closest_vehicle

