        return image_patch

    rider_centers = [(r.left + r.right) / 2, (r.lower + r.upper) / 2] for r in rider_patches]
    horse_centers = [(h.left + h.right) / 2, (h.lower + h.upper) / 2] for h in horse_patches]

    distances = []
    for i, rider_center in enumerate(rider_centers):
        min_distance = float('inf')
        for j, horse_center in enumerate(horse_centers):
            if i == j:
                continue
            dist = math.sqrt((rider_center[0] - horse_center[0]) ** 2 + (rider_center[1] - horse_center[1]) ** 2)
            if dist < min_distance:
                min_distance = dist
        distances.append(min_distance)

    nearest_rider_index = distances.index(min(distances))
    return rider_patches[nearest_rider_index]

